clc
clear
%[text] ## Generate a DOGPUP mesh
%[text] *Meshing is facilitated by the iso2mesh toolbox, see:* [*https://iso2mesh.sourceforge.net/cgi-bin/index.cgi*](https://iso2mesh.sourceforge.net/cgi-bin/index.cgi) *and* [*https://github.com/fangq/iso2mesh*](https://github.com/fangq/iso2mesh) 
[node,~,elem] = meshabox([0 0 0],[60 30 60],1.2); % 60 x 30 x 60 mm mesh %[output:1a62749f]
elem = elem(:,1:4);
[node,elem] = sortmesh([],node,elem); % optimise node and element ordering

% initialise DOGPUP mesh
mua = 0.008; % absorption (mm^-1)
musp = 0.8; % reduced scattering (mm^-1)
nr = 1.4; % refractive index
mesh = dMesh(node,elem,nr,[mua musp]);

% plot mesh
figure %[output:1caf63ff]
mesh.plotdmesh(0.9) % mesh opactity as input %[output:1caf63ff]
title('DOGPUP mesh') %[output:1caf63ff]

% plot mesh optical proeprties
figure %[output:5d4c440a]
tiledlayout(2,3,"TileIndexing","columnmajor") %[output:5d4c440a]
nexttile %[output:5d4c440a]
mesh.plotfun_slice(mesh.mua,hot,'z=30') %[output:5d4c440a]
title('\mu_a @ z = 30') %[output:5d4c440a]
nexttile %[output:5d4c440a]
mesh.plotfun_slice(mesh.musp,hot,'z=30') %[output:5d4c440a]
title('\mu_s'' @ z = 30') %[output:5d4c440a]
nexttile %[output:5d4c440a]
mesh.plotfun_slice(mesh.mua,hot,'x=30') %[output:5d4c440a]
title('\mu_a @ x = 30') %[output:5d4c440a]
nexttile %[output:5d4c440a]
mesh.plotfun_slice(mesh.musp,hot,'x=30') %[output:5d4c440a]
title('\mu_s'' @ x = 30') %[output:5d4c440a]
nexttile %[output:5d4c440a]
mesh.plotfun_slice(mesh.mua,hot,'y=15') %[output:5d4c440a]
title('\mu_a @ y = 15') %[output:5d4c440a]
nexttile %[output:5d4c440a]
mesh.plotfun_slice(mesh.musp,hot,'y=15') %[output:5d4c440a]
title('\mu_s'' @ y = 15') %[output:5d4c440a]
%%
%[text] ## **Update optical properties**
%[text] Add some noise to the absorption and reduced scattering.
% add gaussian white noise
mua_i = mua.*0.05.*randn(size(mesh.mua)) + mua;
musp_i = musp.*0.05.*randn(size(mesh.mua)) + musp;
% update
mesh.update_properties([mua_i musp_i]);

% plotting
figure %[output:57222b46]
tiledlayout(2,3,"TileIndexing","columnmajor") %[output:57222b46]
nexttile %[output:57222b46]
mesh.plotfun_slice(mesh.mua,hot,'z=30') %[output:57222b46]
title('\mu_a @ z = 30') %[output:57222b46]
nexttile %[output:57222b46]
mesh.plotfun_slice(mesh.musp,hot,'z=30') %[output:57222b46]
title('\mu_s'' @ z = 30') %[output:57222b46]
nexttile %[output:57222b46]
mesh.plotfun_slice(mesh.mua,hot,'x=30') %[output:57222b46]
title('\mu_a @ x = 30') %[output:57222b46]
nexttile %[output:57222b46]
mesh.plotfun_slice(mesh.musp,hot,'x=30') %[output:57222b46]
title('\mu_s'' @ x = 30') %[output:57222b46]
nexttile %[output:57222b46]
mesh.plotfun_slice(mesh.mua,hot,'y=15') %[output:57222b46]
title('\mu_a @ y = 15') %[output:57222b46]
nexttile %[output:57222b46]
mesh.plotfun_slice(mesh.musp,hot,'y=15') %[output:57222b46]
title('\mu_s'' @ y = 15') %[output:57222b46]
%%
%[text] Add spherical inclusions
incl = [50 17 30 5; 30 13 40 5]; % inclusion position and radius

% index inclusion 1 usinf equation of sphere 
idx1 = (mesh.node(:,1) - incl(1,1)).^2 + (mesh.node(:,2) - incl(1,2)).^2 + (mesh.node(:,3) - incl(1,3)).^2 < incl(1,4)^2;
% index inclusion 2 usinf equation of sphere 
idx2 = (mesh.node(:,1) - incl(2,1)).^2 + (mesh.node(:,2) - incl(2,2)).^2 + (mesh.node(:,3) - incl(2,3)).^2 < incl(1,4)^2;

% update properties
mua_i(idx1) = 0.015;
musp_i(idx2) = 1.2;
mesh.update_properties([mua_i musp_i]);

% plotting
figure %[output:8c6add97]
tiledlayout(2,3,"TileIndexing","columnmajor") %[output:8c6add97]
nexttile %[output:8c6add97]
mesh.plotfun_slice(mesh.mua,hot,'z=30',incl(1,:)) %[output:8c6add97]
title('\mu_a @ z = 30') %[output:8c6add97]
nexttile %[output:8c6add97]
mesh.plotfun_slice(mesh.musp,hot,'z=30',incl(2,:)) %[output:8c6add97]
title('\mu_s'' @ z = 30') %[output:8c6add97]
nexttile %[output:8c6add97]
mesh.plotfun_slice(mesh.mua,hot,'x=30',incl(1,:)) %[output:8c6add97]
title('\mu_a @ x = 30') %[output:8c6add97]
nexttile %[output:8c6add97]
mesh.plotfun_slice(mesh.musp,hot,'x=30',incl(2,:)) %[output:8c6add97]
title('\mu_s'' @ x = 30') %[output:8c6add97]
nexttile %[output:8c6add97]
mesh.plotfun_slice(mesh.mua,hot,'y=15',incl(1,:)) %[output:8c6add97]
title('\mu_a @ y = 15') %[output:8c6add97]
nexttile %[output:8c6add97]
mesh.plotfun_slice(mesh.musp,hot,'y=15',incl(2,:)) %[output:8c6add97]
title('\mu_s'' @ y = 15') %[output:8c6add97]
figure %[output:348509f2]
tiledlayout(2,2) %[output:348509f2]
% Plot isosurfaces of optical properties
nexttile %[output:348509f2]
mesh.plotfun_iso(mesh.mua) %[output:348509f2]
title('\mu_a') %[output:348509f2]
nexttile %[output:348509f2]
mesh.plotfun_iso(mesh.musp) %[output:348509f2]
title('\mu_s''') %[output:348509f2]
% Plot sliced mesh of optical properties
nexttile %[output:348509f2]
mesh.plotfun_3d(mesh.mua,hot,1,'z>=30') %[output:348509f2]
nexttile %[output:348509f2]
mesh.plotfun_3d(mesh.musp,hot,1,'y<=13') %[output:348509f2]
%%
%[text] ## Add sources and detectors
%[text] use DOGPUP optode object to place array of sources and detectors on mesh
% Initialise optode class

% Source stats
dt = 50e-12;
tAxis = 0:dt:(140*dt);
% IRF
fwhm = 250e-12;
time_dev = fwhm./(2*sqrt(2*log(2)));
irf = exp(-((tAxis-6.*time_dev).^2)./(2.*(time_dev).^2)); % irf is defined as the same for all channels 
Nf = 30; % number of Fourier series coefficients for decomposition

% Optode locations
origin = [30 35 30];
[X,Z] = meshgrid(linspace(-15,15,3),linspace(-15,15,3));
% source locations
Xs = X(1:2:end).';
Zs = Z(1:2:end).';
s_pos = origin + [Xs zeros(numel(Xs),1) Zs];
% source locations
Xs = X(2:2:end-1).';
Zs = Z(2:2:end-1).';
d_pos = origin + [Xs zeros(numel(Xs),1) Zs];
% source-detector links, set here to link all sources and detectors
link = repelem((1:size(s_pos,1)).',size(d_pos,1));
link = cat(2,link,kron(ones(size(s_pos,1),1),(1:size(d_pos,1)).'));

% initialise DOGPUP optode object
optode = dOptode(s_pos,d_pos,link,irf,tAxis,Nf);

figure %[output:61682732]
hold on %[output:61682732]
plotdmesh(mesh,0.9) %[output:61682732]
scatter3(optode.s_positions(:,3),optode.s_positions(:,1),optode.s_positions(:,2),20,'r','filled') %[output:61682732]
scatter3(optode.d_positions(:,3),optode.d_positions(:,1),optode.d_positions(:,2),20,'b','filled') %[output:61682732]
view(-37,12) %[output:61682732]
title('Optodes uninitialised on mesh') %[output:61682732]
%%
%[text] Adding optode to mesh snaps the optodes to the nearest surface
mesh.add_optode(optode);
figure %[output:1162a9d7]
mesh.plotdmesh_snd(0.9) %[output:1162a9d7]
view(-37,12) %[output:1162a9d7]
title('Optodes initialised on mesh') %[output:1162a9d7]
%[text] DOGPUP mesh class references optode handle, so any modification to optode properties are reflected in the mesh object
optode.s_positions(3,:) = optode.s_positions(3,:) + [0 10 0];

figure %[output:4f1facac]
mesh.plotdmesh_snd(0.9) %[output:4f1facac]
view(-37,12) %[output:4f1facac]
title('Shifted source positon') %[output:4f1facac]
optode.s_positions(3,:) = optode.s_positions(3,:) - [0 10 0]; % reset
%[text] If you want more than one instance of the optodes the class is copyable. Manipulating copied optode does not affect mesh.
optode_c = copy(optode);
optode_c.s_positions = optode_c.s_positions+ [0 10 0];

figure %[output:6031941b]
mesh.plotdmesh_snd(0.9) %[output:6031941b]
view(-37,12) %[output:6031941b]
title('Un-shifted source positon') %[output:6031941b]
%[text] The same is true for the mesh object, you must explicitly copy the object to duplicate
mesh2 = copy(mesh);

